const MEAT_RE =
  /\b(chickens?|poussins?|hens?|roosters?|beef|lambs?|mutton|goats?|veal|turkeys?|ducks?|duck breasts?|geese|goose|quails?|pigeons?|squabs?|rabbits?|venison|camel|beef steaks?|brisket|chicken (breasts?|thighs?|wings?|drumsticks?)|lamb chops?|mince|minced meat|ground (beef|lamb|chicken|turkey)|meat|meats|meatballs?|kebab meat|shawarma meat|sucuk|sujuk|beef chorizo|beef bacon|turkey bacon|pastirma|basturma|merguez|liver|kidneys?|oxtail|tripe|bone broth|gelatin|gelatine|chicken stock|beef stock|lamb stock|stock cubes?|bouillon)\b/;
const MEAT_EXCLUDE = /\b(vegetable stock|vegetable bouillon|meat-free|plant-based|coconut meat|vegan meatballs?|veggie meatballs?|hen of the woods|goat'?s? cheese|goat'?s? milk|kidney beans?|chicken of the woods)\b/;
const SEAFOOD_RULES = ALLERGEN_RULES.filter((r) => r.name === 'Fish' || r.name === 'Shellfish');

function normalize(s: string) {
  return s.toLowerCase().replace(/[’`]/g, "'").replace(/\s+/g, ' ').trim();
}

function matchesRule(rule: AllergenRule, ingredient: string): boolean {
  const n = normalize(ingredient);
  if (!rule.include.test(n)) return false;
  if (!rule.exclude) return true;
  // Excluded phrase only cancels the match if nothing else in the name matches.
  const stripped = n.replace(new RegExp(rule.exclude.source, 'g'), ' ');
  return rule.include.test(stripped);
}

/** Allergen names (from ALLERGEN_RULES) found in a list of ingredient names. */
function detectAllergens(ingredients: string[]): Set<string> {
  const found = new Set<string>();
  for (const rule of ALLERGEN_RULES) {
    if (ingredients.some((i) => matchesRule(rule, i))) found.add(rule.name);
  }
  return found;
}

/** Finds the rule for something a user typed or picked, e.g. "Milk" → Dairy, "Nuts" → Tree nuts. */
function ruleForAllergy(allergy: string): AllergenRule | undefined {
  const a = normalize(allergy);
  return ALLERGEN_RULES.find((r) => normalize(r.name) === a || r.aliases.includes(a));
}

function singular(word: string) {
  if (word.endsWith('ies')) return word.slice(0, -3) + 'y';
  if (word.endsWith('oes')) return word.slice(0, -2);
  if (word.length > 3 && word.endsWith('s') && !word.endsWith('ss')) return word.slice(0, -1);
  return word;
}

/**
 * True when a recipe is unsafe for someone with any of `allergies`.
 * Known allergens use the rules (plus the recipe's own tags); anything else the
 * user typed ("mushroom", "coriander") is matched against ingredient names.
 */
function conflictsWithAllergies(
  ingredients: string[],
  allergies: string[],
  taggedAllergens: string[] = []
): boolean {
  if (allergies.length === 0) return false;
  const detected = detectAllergens(ingredients);
  const tagged = new Set(taggedAllergens.map((t) => ruleForAllergy(t)?.name ?? normalize(t)));
  const names = ingredients.map(normalize);
  return allergies.some((allergy) => {
    const rule = ruleForAllergy(allergy);
    if (rule) return detected.has(rule.name) || tagged.has(rule.name);
    const word = singular(normalize(allergy));
    if (!word) return false;
    return tagged.has(normalize(allergy)) || names.some((n) => n.split(/[^a-z']+/).map(singular).join(' ').includes(word));
  });
}

type Diet = 'Vegetarian' | 'Vegan' | 'Pescatarian' | 'Gluten-free' | 'Dairy-free' | 'Low-carb' | 'High-protein' | 'Kid-friendly';

function hasMeat(ingredients: string[]): boolean {
  return ingredients.some((i) => {
    const n = normalize(i);
    return MEAT_RE.test(n) && !MEAT_EXCLUDE.test(n);
  });
}

function hasSeafood(ingredients: string[]): boolean {
  return ingredients.some((i) => SEAFOOD_RULES.some((r) => matchesRule(r, i)));
}

/**
 * True when a recipe suits a dietary preference. Nutrition-based diets use the
 * recipe's numbers; "Kid-friendly" relies on the recipe's tag.
 */
function fitsDiet(
  diet: string,
  recipe: { ingredients: string[]; tags?: string[]; protein?: number | null; carbs?: number | null }
): boolean {
  const tags = new Set((recipe.tags ?? []).map(normalize));
  const allergens = detectAllergens(recipe.ingredients);
  switch (normalize(diet)) {
    case 'vegetarian':
      return !hasMeat(recipe.ingredients) && !hasSeafood(recipe.ingredients);
    case 'vegan':
      return (
        !hasMeat(recipe.ingredients) &&
        !hasSeafood(recipe.ingredients) &&
        !allergens.has('Dairy') &&
        !allergens.has('Eggs') &&
        !recipe.ingredients.some((i) => /\bhoney\b/.test(normalize(i)))
      );
    case 'pescatarian':
      return !hasMeat(recipe.ingredients);
    case 'gluten-free':
      return !allergens.has('Gluten');
    case 'dairy-free':
      return !allergens.has('Dairy');
    case 'low-carb':
      return recipe.carbs != null ? recipe.carbs <= 25 : tags.has('low-carb');
    case 'high-protein':
      return recipe.protein != null ? recipe.protein >= 25 : tags.has('high-protein');
    case 'kid-friendly':
      return tags.has('kid-friendly');
    case 'halal':
      // Every Firdam recipe is halal.
      return true;
    default:
      // Unknown preference from the database: trust a matching tag if there is one.
      return tags.size === 0 || tags.has(normalize(diet));
  }
}

/** Allergens offered in filters when the database list is empty. */
const DEFAULT_ALLERGENS = ALLERGEN_RULES.map((r) => r.name);

// ── inlined from halal.ts ──
/**
 * Words that make a recipe not halal. Checked in ingredient names and method
 * text. Shared by the recipe library builder (supabase/seed/build-recipes.mts),
 * the AI functions (which also refuse haram requests) and, as generated SQL,
 * the database checks that keep haram food out of pantries and shopping lists.
 */
const HARAM: { re: RegExp; why: string; ingredientsOnly?: boolean }[] = [
  { re: /\b(pork|pig|pigs|swine|lard|lardons|pancetta|prosciutto|pepperoni|guanciale|gammon|crackling|mortadella|speck|chicharr[oó]n(es)?)\b/i, why: 'pork' },
  // Bacon and ham are fine only when they say what they are made from.
  { re: /\b(?<!beef |chicken |turkey |halal )(bacon|hams?|jam[oó]n)\b/i, why: 'pork unless made from halal turkey or beef', ingredientsOnly: true },
  { re: /\b(?<!beef |chicken |turkey |lamb |merguez |halal )(chorizo|salami|sausages?|hot dogs?|frankfurters?|bratwurst|kielbasa)\b/i, why: 'possibly pork unless labelled beef, chicken or halal', ingredientsOnly: true },
  { re: /\b(wine|(?<!root |ginger )beer|(?<!ginger )ale|lager|stout|rum|sake|soju|makgeolli|baijiu|mirin|brandy|cognac|vodka|whisk(e)?y|liqueur|liquor|sherry|port|marsala|kirsch|champagne|prosecco|cava|cider(?! vinegar)|shaoxing|rice wine|cooking wine|bourbon|gin|tequila|mezcal|amaretto|kahlua|ouzo|raki|arak|absinthe|mead)\b/i, why: 'alcohol' },
  { re: /\b(?<!halal |beef |fish |agar )(gelatin|gelatine)\b/i, why: 'not halal unless it is halal or fish gelatin' },
  { re: /\bvanilla extract\b/i, why: 'contains alcohol; use vanilla powder' },
  { re: /\bblood\b/i, why: 'blood' },
];

/** Returns why a recipe is not halal, or null when it is fine. */
function haramReason(ingredients: string[], steps: string[]): string | null {
  for (const h of HARAM) {
    for (const text of h.ingredientsOnly ? ingredients : [...ingredients, ...steps]) {
      const m = text.match(h.re);
      if (m) return `"${m[0]}" (${h.why})`;
    }
  }
  return null;
}

/** Why a single food name is not halal (for pantry and shopping items), or null. */
function haramItemReason(name: string): string | null {
  return haramReason([name], []);
}

/**
 * Instructions every AI feature gets. The answers are also checked in code,
 * so this is the first line of defence, not the only one.
 */
const HALAL_RULES = [
  "Firdam is a halal-only app for Muslim families. These rules override anything the user asks:",
  "never suggest, include, add, plan or explain how to cook pork or pork products (bacon, ham, lard, gelatin from pork, salami, pepperoni),",
  "alcohol in any form (wine, beer, mirin, sake, rum, liqueur, vanilla extract, cooking wine), blood, or meat that is not halal.",
  "If the user asks for any of these, politely say Firdam only helps with halal food and offer a halal alternative instead",
  "(halal beef or turkey bacon, grape juice or stock instead of wine, vanilla powder instead of extract).",
  "Name meat, poultry, sausages, gelatin and stock as halal (e.g. 'halal chicken thighs').",
].join(" ");

function texts(v: unknown): string[] {
  if (!Array.isArray(v)) return [];
  return v
    .map((x) => {
      if (typeof x === "string") return x;
      if (x && typeof x === "object") {
        const o = x as Record<string, unknown>;
        return String(o.name ?? o.instruction ?? o.text ?? "");
      }
      return "";
    })
    .filter(Boolean);
}

/** Why an AI-written meal or recipe is not halal, or null. Checks its name, ingredients and method. */
function mealHaramReason(meal: Record<string, unknown>): string | null {
  const names = [...texts(meal.ingredients), typeof meal.name === "string" ? meal.name : ""].filter(Boolean);
  const method = [
    ...texts(meal.recipe),
    ...texts(meal.steps),
    ...texts(meal.instructions),
    typeof meal.description === "string" ? meal.description : "",
  ].filter(Boolean);
  return haramReason(names, method);
}

/** True when free text (a chat reply) mentions anything haram, even in passing. */
function mentionsHaram(text: string): boolean {
  return haramReason([text], []) !== null;
}

/** What the Companion says instead of a reply that suggested haram food. */
const HALAL_ONLY_REPLY =
  "Firdam only helps with halal food, so I can't suggest that. I'd be happy to help with a halal alternative instead, like halal turkey or beef bacon, halal beef sausages, grape juice or stock instead of wine, or vanilla powder instead of vanilla extract.";

/** A friendly message when someone tries to add a haram food, or null if it is fine. */
function haramItemMessage(name: string): string | null {
  const why = haramItemReason(name);
  if (!why) return null;
  return `Firdam only keeps halal food, so ${why} can't be added. Try a halal alternative, like halal turkey bacon, halal beef sausages or grape juice.`;
}

/**
 * Safety rules for school lunchboxes. Every lunchbox Firdam shows, from the
 * library, from leftovers or written by the AI, must pass lunchboxProblem():
 *
 *  - never nuts: no peanuts, tree nuts, nut butters, nut oils or nut spreads
 *    (many schools worldwide are nut-free), whatever the family's allergies;
 *  - halal only;
 *  - none of the children's allergies;
 *  - no choking hazards for children under 4 (whole grapes, popcorn, hard candy…);
 *  - no sweets, candy, soda or energy drinks as part of the lunch.
 *
 * The AI is told these rules, and its answers are checked again here, because
 * a model can still get it wrong.
 */

/** Allergies every lunchbox avoids, on top of each child's own. */
const ALWAYS_AVOID = ["Peanuts", "Tree nuts"];

const NUT_WORDS =
  /\b(nutella|praline|marzipan|frangipane|gianduja|nougat|baklava|nut (butter|spread|oil|bar|mix)|trail mix|almond|walnut|pecan|cashew|pistachio|hazelnut|macadamia|pine nut|brazil nut|peanut|groundnut|satay)/i;
const NOT_A_NUT = /\b(nut[- ]free|nutmeg|coconut|doughnut|butternut|water chestnut)\b/gi;

const CHOKING_UNDER_4 =
  /\b(whole (grapes?|cherry tomato(es)?|olives?|blueberries)|popcorn|hard cand(y|ies)|lollipops?|marshmallows?|gum|chewing gum|hot dogs?|sausage coins|whole nuts|seeds? mix|raw carrot coins|chunks? of raw apple)\b/i;
const SWEETS = /\b(cand(y|ies)|chocolate bar|lollipops?|soda|soft drink|energy drink|gummies|gummy bears?|marshmallows?|cookies? with chocolate)\b/i;

interface LunchboxLike {
  name: string;
  items: string[];
  fun_tip?: string;
}

/** Why a lunchbox can't be shown to these children, or null when it's safe. */
function lunchboxProblem(box: LunchboxLike, allergies: string[], youngestAge: number | null): string | null {
  const text = [box.name, ...box.items, box.fun_tip ?? ""].join(" \n ");
  const withoutSafeWords = text.replace(NOT_A_NUT, " ");
  if (NUT_WORDS.test(withoutSafeWords)) return "contains nuts";
  const found = detectAllergens(box.items);
  if (found.has("Peanuts") || found.has("Tree nuts")) return "contains nuts";
  const halal = haramReason(box.items, [box.fun_tip ?? ""]);
  if (halal) return `not halal (${halal})`;
  if (allergies.length && conflictsWithAllergies(box.items, allergies)) return "contains an allergy";
  if (youngestAge !== null && youngestAge < 4 && CHOKING_UNDER_4.test(text)) return "choking risk for under-4s";
  if (SWEETS.test(text)) return "sweets";
  return null;
}

/** Instructions for the AI. The same rules are checked again after it answers. */
function lunchboxRules(allergies: string[], youngestAge: number | null): string {
  return [
    "You plan school lunchboxes for Muslim children. These rules can never be broken:",
    "1. NO NUTS, EVER: no peanuts, no tree nuts (almonds, walnuts, cashews, pistachios, hazelnuts, pecans, pine nuts…), no nut butters, nut oils, Nutella, praline, marzipan, baklava, nut bars or trail mix. Schools are nut-free.",
    `2. ${HALAL_RULES}`,
    allergies.length
      ? `3. The children are allergic to: ${allergies.join(", ")}. Never include these or anything that contains them.`
      : "3. Respect the children's allergies (none given besides nuts).",
    "4. Everything is eaten cold or at room temperature: no microwave. Perishable food is packed with an ice pack.",
    youngestAge !== null && youngestAge < 4
      ? "5. A child is under 4: cut grapes, cherry tomatoes, olives and blueberries in halves or quarters, use soft or thin pieces, and never include popcorn, whole grapes, hard candy, marshmallows or hot dogs."
      : "5. Cut food into easy, bite-size pieces for children.",
    "6. Healthy and simple: a main, a vegetable, a fruit and a small extra. No candy, chocolate bars, soda or sweet drinks. Ready in about 10 minutes, with ingredients from a normal grocery store.",
    "7. Make it fun for kids: a playful name, and a 'fun tip' (a face, a shape, a story) that makes children want to eat the vegetables.",
  ].join("\n");
}

// ── lunchbox ──
/**
 * Lunchbox planner: a week (Monday–Friday) of school lunchboxes for the
 * children, 3 options a day for the child to choose from.
 *
 * POST { action: "plan", weekStart: "2026-11-09", children: [{ name, age, allergies }],
 *        allergies?: string[], leftovers?: [{ date, name, ingredients }] }
 *   Uses the shared library first (free, unlimited). Last night's dinner becomes
 *   a leftover option. Only when the library can't cover the week safely does
 *   the AI write new ideas (counted as "lunchbox_ai"); those that pass the
 *   checks join the library, so every family benefits and each picture is made once.
 *
 * Admin: POST { action: "images", limit?: 1–3 } makes pictures for ideas that have none;
 *        POST { action: "translate", limit?: 1–20 } adds French and Arabic text.
 *        Allowed for Firdam admins, or with header x-lunchbox-token (the Vault secret
 *        "lunchbox_admin_token", used by the daily database job "lunchbox-library").
 *
 * Every lunchbox passes lunchboxProblem(): never nuts, halal only, none of the
 * children's allergies, no choking hazards for under-4s, no sweets.
 */

const MODEL = "gpt-4o-mini";
const FREE_AI_PER_MONTH = 2;
const PAID_AI_PER_MONTH = 8;
const DAYS = 5;
const OPTIONS = 3;

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Client-Info, Apikey",
};

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });
}
function env(name: string): string | undefined {
  const v = Deno.env.get(name);
  return v && v.trim() ? v.trim() : undefined;
}

async function rest<T>(path: string, init: RequestInit = {}): Promise<T> {
  const url = env("SUPABASE_URL")!;
  const key = env("SUPABASE_SERVICE_ROLE_KEY")!;
  const res = await fetch(`${url}/rest/v1/${path}`, {
    ...init,
    headers: { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "application/json", ...(init.headers ?? {}) },
  });
  if (!res.ok) throw new Error(`Database error ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const text = await res.text();
  return (text ? JSON.parse(text) : null) as T;
}

interface Idea extends LunchboxLike {
  id: string;
  fun_tip: string;
  tools: string[];
  tags: string[];
  min_age: number;
  image_path: string | null;
  source: string;
  i18n: Record<string, unknown>;
}

interface Child {
  name: string;
  age: number | null;
  allergies: string[];
}

type Option =
  | { kind: "idea"; id: string }
  | { kind: "leftover"; dinner: string; name: string; items: string[]; fun_tip: string; tools: string[] };

function shuffle<T>(a: T[]): T[] {
  const b = [...a];
  for (let i = b.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [b[i], b[j]] = [b[j], b[i]];
  }
  return b;
}

function addDays(iso: string, n: number): string {
  const d = new Date(iso + "T12:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

/**
 * Last night's dinner as a lunchbox, if it's safe for these children. The
 * dinner's ingredients are checked too (a dish name alone can hide nuts).
 */
function leftoverOption(dinner: string, ingredients: string[], allergies: string[], youngest: number | null): Option | null {
  const name = dinner.trim().slice(0, 60);
  if (!name) return null;
  const box = {
    name: `Leftover ${name}`,
    items: [`${name} from last night (cold or at room temperature)`, "a wrap, rice or bread", "cucumber or carrot sticks", "a piece of fruit"],
    fun_tip: "Turn last night's dinner into a new lunch: roll it in a wrap and cut it into pinwheels.",
  };
  if (lunchboxProblem({ ...box, items: [...box.items, ...ingredients] }, allergies, youngest)) return null;
  return { kind: "leftover", dinner: name, ...box, tools: ["sandwich wrap paper", "bento lunch box"] };
}

/** Asks the AI for new lunchbox ideas and keeps only those that pass every check. */
async function aiIdeas(count: number, allergies: string[], youngest: number | null, avoidNames: string[]): Promise<(LunchboxLike & { tools: string[]; tags: string[] })[]> {
  const apiKey = env("OPENAI_API_KEY");
  if (!apiKey) throw new Error("AI is not set up.");
  const res = await fetchOpenAI(apiKey, {
    model: MODEL,
    temperature: 0.9,
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: lunchboxRules(allergies, youngest) },
      {
        role: "user",
        content:
          `Write ${count} different school lunchbox ideas${youngest !== null ? ` for children aged ${youngest} and up` : ""}. ` +
          `Don't repeat these: ${avoidNames.slice(0, 60).join("; ")}. ` +
          `Answer as JSON: {"lunchboxes":[{"name":"playful name, max 40 characters","items":["4 to 6 items with simple amounts"],"fun_tip":"one sentence","tools":["1 to 3 reusable kitchen tools to make it, e.g. star cookie cutter, bento box, food picks"],"tags":["vegetarian" or "pescatarian" or "gluten-free", if true]}]}`,
      },
    ],
  });
  if (!res.ok) {
    const failure = await describeOpenAIFailure(res);
    throw new Error(failure.message);
  }
  const data = (await res.json()) as { choices?: { message?: { content?: string } }[] };
  let parsed: { lunchboxes?: unknown[] } = {};
  try {
    parsed = JSON.parse(data.choices?.[0]?.message?.content ?? "{}");
  } catch {
    return [];
  }
  const out: (LunchboxLike & { tools: string[]; tags: string[] })[] = [];
  for (const raw of parsed.lunchboxes ?? []) {
    const o = raw as Record<string, unknown>;
    const box = {
      name: String(o.name ?? "").trim().slice(0, 80),
      items: (Array.isArray(o.items) ? o.items : []).map((x) => String(x).trim().slice(0, 140)).filter(Boolean).slice(0, 8),
      fun_tip: String(o.fun_tip ?? "").trim().slice(0, 280),
      tools: (Array.isArray(o.tools) ? o.tools : []).map((x) => String(x).trim().slice(0, 50)).filter(Boolean).slice(0, 3),
      tags: (Array.isArray(o.tags) ? o.tags : []).map((x) => String(x).toLowerCase()).filter((t) => ["vegetarian", "pescatarian", "gluten-free"].includes(t)),
    };
    if (box.name.length < 2 || box.items.length < 2 || !box.fun_tip) continue;
    const problem = lunchboxProblem(box, allergies, youngest);
    if (problem) {
      console.error(`AI lunchbox rejected (${problem}): ${box.name}`);
      continue;
    }
    out.push(box);
  }
  return out;
}

function lunchboxImagePrompt(idea: LunchboxLike): string {
  return [
    `Realistic overhead photograph of a child's school lunchbox called "${idea.name}": an open bento lunch box with compartments containing exactly:`,
    idea.items.join("; ") + ".",
    idea.fun_tip ? `Arranged in a fun, playful way for kids: ${idea.fun_tip}` : "",
    "Real food, neatly cut, bright natural colours, on a light wooden kitchen table with a small cloth napkin, soft daylight.",
    "Halal food only. Absolutely no nuts, no peanuts, no candy. No text, no logos, no people, no hands.",
  ]
    .filter(Boolean)
    .join(" ");
}

/** Makes and stores the picture for one idea (checked by a vision model). */
async function pictureFor(idea: Idea): Promise<string | null> {
  const apiKey = env("OPENAI_API_KEY");
  if (!apiKey) return null;
  const { model, quality } = imageModel();
  let reason = "";
  for (let attempt = 1; attempt <= 2; attempt++) {
    const prompt = lunchboxImagePrompt(idea) + (reason ? ` IMPORTANT: the last picture was wrong (${reason}). Show exactly the food listed.` : "");
    const bytes = await generateFoodImage(apiKey, prompt, model, quality);
    let ok = true;
    try {
      const check = await photoMatchesDish(apiKey, bytes, `a kids' lunchbox with ${idea.items.join(", ")}`);
      ok = check.ok;
      reason = check.reason;
    } catch {
      ok = true;
    }
    if (ok) {
      const url = await uploadFoodImage(`lunchbox/${imageSlug(idea.name)}-${idea.id.slice(0, 8)}.webp`, bytes);
      await rest(`lunchbox_ideas?id=eq.${idea.id}`, { method: "PATCH", body: JSON.stringify({ image_path: url }) });
      return url;
    }
  }
  return null;
}

async function translateIdeas(ideas: Idea[]): Promise<number> {
  const apiKey = env("OPENAI_API_KEY");
  if (!apiKey || !ideas.length) return 0;
  const res = await fetchOpenAI(apiKey, {
    model: MODEL,
    temperature: 0.2,
    response_format: { type: "json_object" },
    messages: [
      {
        role: "system",
        content:
          "Translate children's lunchbox ideas from English into natural French and Modern Standard Arabic for Muslim families. Keep amounts, keep 'halal', keep it short and warm. Answer JSON only.",
      },
      {
        role: "user",
        content:
          `Translate each: ${JSON.stringify(ideas.map((i) => ({ id: i.id, name: i.name, items: i.items, fun_tip: i.fun_tip, tools: i.tools })))}\n` +
          `Answer as {"items":[{"id":"...","fr":{"name":"","items":[],"fun_tip":"","tools":[]},"ar":{"name":"","items":[],"fun_tip":"","tools":[]}}]}`,
      },
    ],
  });
  if (!res.ok) throw new Error((await describeOpenAIFailure(res)).message);
  const data = (await res.json()) as { choices?: { message?: { content?: string } }[] };
  const parsed = JSON.parse(data.choices?.[0]?.message?.content ?? "{}") as { items?: { id: string; fr?: unknown; ar?: unknown }[] };
  let n = 0;
  for (const t of parsed.items ?? []) {
    const idea = ideas.find((i) => i.id === t.id);
    if (!idea || !t.fr || !t.ar) continue;
    await rest(`lunchbox_ideas?id=eq.${idea.id}`, { method: "PATCH", body: JSON.stringify({ i18n: { ...idea.i18n, fr: t.fr, ar: t.ar } }) });
    n++;
  }
  return n;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 200, headers: corsHeaders });
  if (req.method !== "POST") return json({ error: "Use POST." }, 405);
  try {
    const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
    const action = String(body.action ?? "plan");
    const token = req.headers.get("x-lunchbox-token");
    const user = token ? null : await getUser(req);

    if (action === "images" || action === "translate") {
      const allowed = token
        ? (await rest<boolean>("rpc/check_lunchbox_admin_token", { method: "POST", body: JSON.stringify({ p_token: token }) })) === true
        : !!user && (await isAdminUser(user.id));
      if (!allowed) return json({ error: "Admins only." }, 403);
      if (action === "images") {
        const limit = Math.min(3, Math.max(1, Number(body.limit) || 1));
        const todo = await rest<Idea[]>(`lunchbox_ideas?select=*&image_path=is.null&active=eq.true&order=created_at&limit=${limit}`);
        const made: string[] = [];
        for (const idea of todo) if (await pictureFor(idea)) made.push(idea.name);
        const left = await rest<{ id: string }[]>("lunchbox_ideas?select=id&image_path=is.null&active=eq.true");
        return json({ made, remaining: left.length });
      }
      const limit = Math.min(20, Math.max(1, Number(body.limit) || 10));
      const todo = await rest<Idea[]>(`lunchbox_ideas?select=*&active=eq.true&i18n->fr=is.null&order=created_at&limit=${limit}`);
      const done = await translateIdeas(todo);
      const left = await rest<{ id: string }[]>("lunchbox_ideas?select=id&active=eq.true&i18n->fr=is.null");
      return json({ translated: done, remaining: left.length });
    }

    // ---- plan
    if (!user) return json({ error: "Please sign in." }, 401);
    const weekStart = String(body.weekStart ?? "");
    if (!/^\d{4}-\d{2}-\d{2}$/.test(weekStart)) return json({ error: "Choose a week." }, 400);
    const children: Child[] = (Array.isArray(body.children) ? body.children : [])
      .slice(0, 8)
      .map((c) => {
        const o = c as Record<string, unknown>;
        const age = Number(o.age);
        return {
          name: String(o.name ?? "").trim().slice(0, 40),
          age: Number.isFinite(age) && age > 0 ? Math.floor(age) : null,
          allergies: (Array.isArray(o.allergies) ? o.allergies : []).map((a) => String(a).trim()).filter(Boolean).slice(0, 20),
        };
      });
    if (!children.length) return json({ error: "Choose at least one child." }, 400);
    if (children.some((c) => c.age !== null && c.age < 2)) {
      return json({ error: "Lunchboxes are for children aged 2 and up. Baby meals are coming soon." }, 400);
    }
    const household = (Array.isArray(body.allergies) ? body.allergies : []).map((a) => String(a).trim()).filter(Boolean);
    const allergies = [...new Set([...ALWAYS_AVOID, ...household, ...children.flatMap((c) => c.allergies)])];
    const ages = children.map((c) => c.age).filter((a): a is number => a !== null);
    const youngest = ages.length ? Math.min(...ages) : null;

    const library = await rest<Idea[]>("lunchbox_ideas?select=*&active=eq.true");
    let safe = library.filter((i) => (youngest === null || i.min_age <= Math.max(youngest, 3)) && !lunchboxProblem(i, allergies, youngest));

    // Not enough safe ideas for 3 a day: ask the AI for more (counted against the plan).
    let usedAI = false;
    let aiNote: string | null = null;
    const needed = DAYS * OPTIONS;
    if (safe.length < needed) {
      const plan = await getPlan(user.id);
      const limit = plan === "free" ? FREE_AI_PER_MONTH : PAID_AI_PER_MONTH;
      const used = await countUsageThisMonth(user.id, "lunchbox_ai");
      if (used < limit) {
        try {
          const fresh = await aiIdeas(Math.min(12, needed - safe.length + 4), allergies, youngest, library.map((i) => i.name));
          if (fresh.length) {
            const saved = await rest<Idea[]>("lunchbox_ideas?on_conflict=name", {
              method: "POST",
              headers: { Prefer: "return=representation,resolution=ignore-duplicates" },
              body: JSON.stringify(fresh.map((f) => ({ ...f, min_age: Math.max(2, youngest ?? 3), source: "ai" }))),
            });
            safe = [...safe, ...saved];
            await recordUsage(user.id, "lunchbox_ai");
            usedAI = true;
            // Pictures for the new ideas, in the background (each is made once, then shared).
            // deno-lint-ignore no-explicit-any
            (globalThis as any).EdgeRuntime?.waitUntil?.(
              (async () => {
                for (const idea of saved.slice(0, 6)) await pictureFor(idea).catch((e) => console.error("lunchbox picture", e));
              })(),
            );
          }
        } catch (e) {
          aiNote = (e as Error).message;
        }
      } else {
        aiNote = "limit";
      }
    }
    if (!safe.length) return json({ error: "We couldn't find a lunchbox that fits these allergies yet. Try again later.", aiNote }, 422);

    // Three different options a day; spread ideas across the week before repeating.
    const pool = shuffle(safe);
    let cursor = 0;
    const next = (taken: Set<string>): Idea => {
      for (let tries = 0; tries < pool.length; tries++) {
        const idea = pool[cursor++ % pool.length];
        if (!taken.has(idea.id)) return idea;
      }
      return pool[cursor++ % pool.length];
    };
    const leftovers = (Array.isArray(body.leftovers) ? body.leftovers : []) as { date?: string; name?: string; ingredients?: unknown }[];
    const days = Array.from({ length: DAYS }, (_, d) => {
      const date = addDays(weekStart, d);
      const taken = new Set<string>();
      const options: Option[] = [];
      // Yesterday's dinner (from the meal plan) becomes the first option.
      const dinner = leftovers.find((l) => l.date === addDays(date, -1));
      const dinnerIngredients = (Array.isArray(dinner?.ingredients) ? dinner.ingredients : []).map((x) => String(x).slice(0, 80)).slice(0, 40);
      const left = dinner?.name ? leftoverOption(String(dinner.name), dinnerIngredients, allergies, youngest) : null;
      if (left) options.push(left);
      while (options.length < OPTIONS) {
        const idea = next(taken);
        taken.add(idea.id);
        options.push({ kind: "idea", id: idea.id });
      }
      return { date, options, chosen: null as number | null };
    });

    const ideasUsed = safe.filter((i) => days.some((d) => d.options.some((o) => o.kind === "idea" && o.id === i.id)));
    await rest("lunchbox_plans?on_conflict=user_id,week_start", {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates" },
      body: JSON.stringify({ user_id: user.id, week_start: weekStart, children, days, updated_at: new Date().toISOString() }),
    });
    return json({ weekStart, children, days, ideas: ideasUsed, usedAI, aiNote });
  } catch (e) {
    console.error(e);
    return json({ error: (e as Error).message }, 500);
  }
});
